                    print("  ",port,path,resp.status,resp.headers.get_content_type(),len(resp.read()))
            except Exception as e:
                pass
    p.terminate()
    try:
        out,err=p.communicate(timeout=2)
    except:
        p.kill(); out,err=p.communicate()
    print("stdout",out)
    print("stderr",err)
