    for _ in range(c): v0,v1,v2,v3=sipround(v0,v1,v2,v3)
    v0^=b; v2^=0xff
    for _ in range(d): v0,v1,v2,v3=sipround(v0,v1,v2,v3)
    return (v0^v1^v2^v3)&MASK

