            return f"Usage: {prog} {root_arg} <COMMAND>"
        return f"Usage: {prog} <COMMAND>"
    parts=[f"Usage: {prog} {cmd.name}"]
    present=set(present_opts)
    if extra_opt: present.add(extra_opt)
    if exclude: present.discard(exclude)
    if not present and not positional_present and not extra_opt:
        return standard_usage(cmd,prog)
    for o in cmd.opts:
        if o.dest in present:
            parts.append(o.usage())
    if extra_opt=="help":
        parts.append("--help")
    for p in cmd.pos:
