MAX=18446744073709551615

def _parse_num(text,pos,name,end_required_dot):
    # returns (value,newpos_after_dot_or_at_delim)
    if pos>=len(text):
        raise SemverError(f"unexpected end of input while parsing {name} version number")
    ch=text[pos]
    if not ('0'<=ch<='9'):
        raise SemverError(f"unexpected character '{ch}' while parsing {name} version number")
    start=pos
    val=0
    if ch=='0' and pos+1<len(text) and text[pos+1].isdigit():
        raise SemverError(f"invalid leading zero in {name} version number")
    while pos<len(text) and text[pos].isdigit():
        val=val*10+(ord(text[pos])-48)
        if val>MAX:
            raise SemverError(f"value of {name} version number exceeds u64::MAX")
        pos+=1
    if end_required_dot:
        if pos>=len(text):
            raise SemverError(f"unexpected end of input while parsing {name} version number")
        if text[pos]!='.':
            raise SemverError(f"unexpected character '{text[pos]}' while parsing {name} version number")
        pos+=1
    return val,pos

def _parse_idents(text,pos,kind):
    # kind 'pre-release identifier' or 'build metadata'; parse until end ('+' ends prerelease)
    segments=[]
    start_all=pos
    while True:
        seg_start=pos
        seg=""
        all_digit=True
        while pos<len(text) and (('0'<=text[pos]<='9') or ('A'<=text[pos]<='Z') or ('a'<=text[pos]<='z') or text[pos]=='-'):
            if not text[pos].isdigit(): all_digit=False
            seg+=text[pos]; pos+=1
        if not seg:
            raise SemverError(f"empty identifier segment in {kind}")
        if kind.startswith("pre-release") and all_digit and len(seg)>1 and seg[0]=='0':
            raise SemverError(f"invalid leading zero in pre-release identifier")
        segments.append(seg)
        if pos>=len(text):
            break
        ch=text[pos]
        if ch=='.':
            pos+=1; continue
        if kind.startswith("pre-release") and ch=='+':
            break
        raise SemverError(f"unexpected character '{ch}' after {kind}")
    return ".".join(segments),pos

def parse_semver(text):
    if text=="":
        raise SemverError("empty string, expected a semver version")
    pos=0
    major,pos=_parse_num(text,pos,"major",True)
    minor,pos=_parse_num(text,pos,"minor",True)
    # patch
    if pos>=len(text):
        raise SemverError("unexpected end of input while parsing patch version number")
    patch,pos=_parse_num(text,pos,"patch",False)
    pre="";build=""
    if pos<len(text):
        ch=text[pos]
        if ch=='-':
            pos+=1; pre,pos=_parse_idents(text,pos,"pre-release identifier")
        elif ch=='+':
            pass
        else:
            raise SemverError(f"unexpected character '{ch}' after patch version number")
    if pos<len(text) and text[pos]=='+':
        pos+=1; build,pos=_parse_idents(text,pos,"build metadata")
    return Version(major,minor,patch,pre,build)
