    def __init__(self,globals_extra=None):
        self.cache={};self.globals_extra=globals_extra or {}
    def resolve(self,path,from_interp):
        base=os.path.dirname(os.path.abspath(from_interp.filename)) if from_interp and from_interp.filename else os.getcwd()
        p=path
        if not os.path.isabs(p):p=os.path.normpath(os.path.join(base,p))
        candidates=[p,p+".js",p+".json",os.path.join(p,"index.js")]
        for c in candidates:
            if os.path.isfile(c):return c
        return p
