        rp=self.resolve(path,from_interp)
        if rp in self.cache:return self.cache[rp]
        if rp.endswith(".json"):
            import json as _j
            interp=Interpreter(self,rp,self.globals_extra)
            data=from_plain(_j.load(open(rp)))
            interp.default_export=data;interp.module_obj.props["exports"]=data
            mod=LoadedModule(interp);self.cache[rp]=mod;return mod
        text=open(rp,encoding='utf-8').read()
        interp=Interpreter(self,rp,self.globals_extra)
        self.cache[rp]=LoadedModule(interp)
        program=Parser(Lexer(text,rp).tokenise(),rp).parse_program();interp.run(program)
        return self.cache[rp]
