class Env:
    def __init__(self,parent=None):
        self.vars={};self.parent=parent
    def get(self,name):
        e=self
        while e is not None:
            if name in e.vars:return e.vars[name]
            e=e.parent
        raise JSError(f"{name} is not defined","ReferenceError")
    def find_env(self,name):
        e=self
        while e is not None:
            if name in e.vars:return e
            e=e.parent
        return None
    def set(self,name,value,declare=False):
        if declare:
            self.vars[name]=value;return value
        e=self.find_env(name)
        if e is None:
            # sloppy global
            root=self
            while root.parent is not None:root=root.parent
            root.vars[name]=value;return value
        e.vars[name]=value;return value
    def declare(self,name,value):self.vars[name]=value

def js_truthy(v):
    if v is UNDEFINED or v is None:return False
    if isinstance(v,bool):return v
    if isinstance(v,(int,float)):return v!=0 and not (isinstance(v,float) and math.isnan(v))
    if isinstance(v,str):return len(v)>0
    return True

