    if v is UNDEFINED:return "undefined"
    if v is None:return "null"
    if isinstance(v,bool):return "true" if v else "false"
    if isinstance(v,float):
        if math.isnan(v):return "NaN"
        if math.isinf(v):return "Infinity" if v>0 else "-Infinity"
        if v.is_integer() and abs(v)<1e21:return str(int(v))
        return repr(v)
    if isinstance(v,str):return v
    if isinstance(v,list):return ",".join("" if x is None or x is UNDEFINED else js_to_string(x) for x in v)
    if isinstance(v,JSRegExp):return f"/{v.source}/{v.flags}"
    if isinstance(v,GrammarSymbol):return "[object Object]"
    if isinstance(v,JSObject):return "[object Object]"
    return str(v)

