        p=path
        if not os.path.isabs(p):p=os.path.normpath(os.path.join(base,p))
        candidates=[p,p+".js",p+".json",os.path.join(p,"index.js")]
        for c in candidates:
            if os.path.isfile(c):return c
        return p
    def import_module(self,path,from_interp):
        rp=self.resolve(path,from_interp)
        if rp in self.cache:return self.cache[rp]
        if rp.endswith(".json"):
