        self.cache[rp]=LoadedModule(interp)
        program=Parser(Lexer(text,rp).tokenise(),rp).parse_program();interp.run(program)
        return self.cache[rp]
    def require(self,path,from_interp):
        mod=self.import_module(path,from_interp)
        exp=mod.get_export("default")
        # CommonJS require returns module.exports
        me=mod.interp.module_obj.props.get("exports")
        if me is not UNDEFINED and me is not None:
            # if exports object empty and default exists, default wins for esm transpiled
            if isinstance(me,JSObject) and me.props:return me
            if not isinstance(me,JSObject):return me
        return exp
