def canonical_js_flags(flags):
    order="dgimsuvy";seen=[]
    for c in flags:
        if c not in seen:seen.append(c)
    return "".join(sorted(seen,key=lambda c:order.find(c) if c in order else 99))

def js_value_to_plain(v):
    if v is UNDEFINED:return None
    if isinstance(v,GrammarSymbol):return {"type":"SYMBOL","name":v.name}
    if isinstance(v,JSObject):return {k:js_value_to_plain(x) for k,x in v.props.items() if x is not UNDEFINED}
    if isinstance(v,list):return [js_value_to_plain(x) for x in v]
    if isinstance(v,JSRegExp):
        out={"type":"PATTERN","value":v.source}
        if v.flags:out["flags"]=canonical_js_flags(v.flags)
        return out
    return v

def format_quickjs_error(e,grammar_path):
    # Best-effort QuickJS-like stack. Positions in the DSL implementation
    # cannot be reproduced exactly from a Python interpreter; use the
    # message and type which are the semantically important parts.
    stack_lines=""
    if e.stack:
        parts=[]
        for frame in e.stack:
            if isinstance(frame,tuple) and len(frame)==3:
                fn,l,c=frame;parts.append(f"    at {fn}:{l}:{c}")
        if parts:stack_lines="\n    Stack: "+"\n        ".join(parts).lstrip()
    return f"QuickJS error: Message: {e.message}{stack_lines}\n    \n    Type: {e.etype}"

def load_grammar_js_native(path):
    abspath=os.path.abspath(path)
    loader=ModuleLoader({"__dsl":DSLFactory()})
    try:
        mod=loader.import_module(abspath,None)
    except FileNotFoundError as e:
        raise
    except JSError as e:
        raise TSErr(format_quickjs_error(e,abspath))
    grammar_obj=None
    # result.default?.grammar ?? result.grammar ; module.exports fallback
    default=mod.interp.default_export
    if isinstance(default,JSObject) and "grammar" in default.props:
        grammar_obj=default.props["grammar"]
    if grammar_obj is None:
        # named export grammar ?
        ge=mod.get_export("grammar")
        if isinstance(ge,JSObject) and "grammar" in ge.props:grammar_obj=ge.props["grammar"]
        elif isinstance(ge,JSObject) and ge.props:grammar_obj=ge
    if grammar_obj is None:
        me=mod.interp.module_obj.props.get("exports")
        if isinstance(me,JSObject) and "grammar" in me.props:grammar_obj=me.props["grammar"]
    if grammar_obj is None:
        return {"$schema":"https://tree-sitter.github.io/tree-sitter/assets/schemas/grammar.schema.json"}
    return js_value_to_plain(grammar_obj)
