import re

class RegexError(ValueError):pass

def translate_regex(pattern,flags=""):
    """Translate a JS/Rust regex (as used in tree-sitter grammars) to a Python re pattern.
    Most patterns are already compatible. Handles common differences:
    - \\d \\w \\s etc stay (Python on str is unicode-aware like Rust by default)
    - character class set operations and POSIX classes are left mostly as-is
    - named groups (?P<name>) already Python-compatible; JS (?<name>) converted
    - \\xNN, \\uNNNN escapes converted
    """
    if pattern is None:return ""
    out=[];i=0;n=len(pattern);in_class=False
    while i<n:
        ch=pattern[i]
        if ch=='\\' and i+1<n:
            nxt=pattern[i+1]
            if nxt=='x' and i+3<n:
                # \xNN hex in JS/Rust regex; Python supports \xNN too
                out.append(pattern[i:i+4]);i+=4;continue
            if nxt=='u' and i+2<n and pattern[i+2]=='{':
                end=pattern.find('}',i+2)
                if end>0:
                    code=pattern[i+3:end]
                    try:out.append(chr(int(code,16)) if not in_class else '\\U%08x'%int(code,16))
                    except:out.append('?')
                    i=end+1;continue
            out.append(ch);out.append(nxt);i+=2;continue
        if ch=='[':in_class=True
        if ch==']':in_class=False
        if pattern.startswith('(?<',i) and not pattern.startswith('(?<=',i) and not pattern.startswith('(?<!',i):
            end=pattern.find('>',i)
            if end>0:
                name=pattern[i+3:end];out.append(f'(?P<{name}>');i=end+1;continue
        out.append(ch);i+=1
    pat="".join(out)
    return pat

def compile_regex(pattern,flags=""):
    pyflags=0
    if flags:
        if 'i' in flags:pyflags|=re.IGNORECASE
        if 'm' in flags:pyflags|=re.MULTILINE
        if 's' in flags:pyflags|=re.DOTALL
        if 'x' in flags:pyflags|=re.VERBOSE
    # Inline flags in the pattern itself are honoured by Python too
    try:
        return re.compile(translate_regex(pattern,flags),pyflags)
    except re.error as e:
        raise RegexError(str(e))

def escape_literal(s):
    return re.escape(s)
