import json

class Occ:
    __slots__=("typ","named","field","min","multiple")
    def __init__(self,typ,named,field=None,min=1,multiple=False):
        self.typ=typ;self.named=named;self.field=field;self.min=min;self.multiple=multiple
    def clone(self):return Occ(self.typ,self.named,self.field,self.min,self.multiple)
    def __repr__(self):return f"Occ({self.typ},{self.named},f={self.field},min={self.min},mult={self.multiple})"

class Analyzer:
    def __init__(self,raw,prepared):
        self.raw=raw;self.pg=prepared
        self.rules=raw.get("rules") or {}
    def symbol_creates_node(self,name):
        return name in self.rules and not self.pg.is_hidden_name(name)
    def is_token_var(self,name):
        sd=self.pg.symbols.get(name);return bool(sd and sd.is_token)
    # Expansion returns list of alternatives, each a list[Occ]
    def expand(self,expr,field=None,alias=None,minv=1,mult=False,visited=()):
        if not isinstance(expr,dict):return [[]]
        t=expr.get("type")
        if t=="BLANK":return [[]]
        if t=="STRING":
            typ,named=(alias if alias else (expr.get("value",""),False))
            return [[Occ(typ,named,field,minv,mult)]]
        if t=="PATTERN":
            if alias:return [[Occ(alias[0],alias[1],field,minv,mult)]]
            return [[]]  # anonymous regex tokens have no stable node type
        if t=="SYMBOL":
            return self.expand_symbol(expr.get("name"),field,alias,minv,mult,visited)
        if t=="SEQ":
            alts=[[]]
            for m in expr.get("members",[]):
                sub=self.expand(m,field,alias,minv,mult,visited)
                new=[]
                for a in alts:
                    for b in sub:new.append(a+[x.clone() for x in b])
                alts=new
                if len(alts)>512:alts=alts[:512]
            return alts
        if t=="CHOICE":
            out=[]
            for m in expr.get("members",[]):out.extend(self.expand(m,field,alias,minv,mult,visited))
            return out or [[]]
        if t=="REPEAT":
            return self.expand(expr.get("content"),field,alias,0,True,visited)
        if t=="REPEAT1":
            return self.expand(expr.get("content"),field,alias,minv,True,visited)
        if t=="FIELD":
            return self.expand(expr.get("content"),expr.get("name"),alias,minv,mult,visited)
        if t=="ALIAS":
            al=(expr.get("value"),bool(expr.get("named")))
            content=expr.get("content")
            # If aliased content is a symbol, renaming is handled by passing alias down.
            return self.expand(content,field,al,minv,mult,visited)
        if t in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC"):
            return self.expand(expr.get("content"),field,alias,minv,mult,visited)
        if t in ("TOKEN","IMMEDIATE_TOKEN"):
            content=expr.get("content")
            if isinstance(content,dict) and content.get("type")=="STRING":
                typ,named=alias if alias else (content.get("value",""),False);return [[Occ(typ,named,field,minv,mult)]]
            if isinstance(content,dict) and content.get("type")=="SYMBOL":
                return self.expand(content,field,alias,minv,mult,visited)
            if alias:return [[Occ(alias[0],alias[1],field,minv,mult)]]
            return [[]]
        if t=="RESERVED":
            return self.expand(expr.get("content"),field,alias,minv,mult,visited)
        return [[]]
    def expand_symbol(self,name,field,alias,minv,mult,visited):
        if name is None:return [[]]
        # external named token
        if name in self.pg.external_names or name not in self.rules:
            if alias:return [[Occ(alias[0],alias[1],field,minv,mult)]]
            visible=not self.pg.is_hidden_name(name)
            return [[Occ(name,visible,field,minv,mult)]] if name in self.pg.external_names else [[]]
        if alias is not None:
            # aliasing a symbol creates/renames a single node
            return [[Occ(alias[0],alias[1],field,minv,mult)]]
        if self.is_token_var(name):
            if self.symbol_creates_node(name):
                return [[Occ(name,True,field,minv,mult)]]
