        if name in visited:
            return [[]]
        return self.expand(self.rules[name],field,alias,minv,mult,visited+(name,))
    def node_info_for(self,name):
        alts=self.expand(self.rules[name],visited=(name,) if self.pg.is_hidden_name(name) else ())
        # For visible symbols, expand() on the rule body itself: visited shouldn't block its own contents.
        if not self.pg.is_hidden_name(name):
            alts=self.expand(self.rules[name])
        fields={}
        # collect field names
        field_names=[]
        for alt in alts:
            for o in alt:
