        child_types=set();child_multiple=False;child_required=True if alts else False;has_children=False
        for alt in alts:
            occ=[o for o in alt if o.field is None and o.named]
            if occ:has_children=True
            for o in occ:child_types.add((o.typ,o.named))
            if len(occ)>1 or any(o.multiple for o in occ):child_multiple=True
            if not any(o.min>=1 for o in occ):child_required=False
