        if has_children:
            children={"multiple":child_multiple,"required":child_required,"types":[{"type":t,"named":n} for t,n in sorted(child_types)]}
        return fields,children
    def subtypes_for(self,name):
        alts=self.expand(self.rules[name])
        types=set()
        for alt in alts:
            for o in alt:types.add((o.typ,o.named))
        return [{"type":t,"named":n} for t,n in sorted(types)]
    def extra_types(self):
        out=set()
        for ex in self.raw.get("extras") or []:
            for alt in self.expand(ex):
                for o in alt:
                    if o.named:out.add(o.typ)
        return out
    def anonymous_types(self):
        out=set()
        def walk(expr,rule_name):
            if not isinstance(expr,dict):return
            t=expr.get("type")
            if t=="STRING":
                # A string that is the entire body of a named rule is that rule's token, not anonymous.
                out.add(expr.get("value",""));return
            for v in expr.values():
                if isinstance(v,dict):walk(v,rule_name)
                elif isinstance(v,list):
                    for x in v:walk(x,rule_name) if isinstance(x,dict) else None
