        # strings in external definitions:
        for ex in self.raw.get("externals") or []:
            if isinstance(ex,dict) and ex.get("type")=="STRING":out.add(ex.get("value",""))
        return out

def generate_node_types(raw,prepared):
    an=Analyzer(raw,prepared)
    extras=an.extra_types();root=prepared.root_name
    composite=[];anonymous=[];leaves=[]
    seen_named=set()
    for name in prepared.rules_order:
        if name in prepared.supertypes:
            entry={"type":name,"named":True}
            if name==root:entry["root"]=True
            if name in extras:entry["extra"]=True
            entry["subtypes"]=an.subtypes_for(name)
            composite.append(entry);seen_named.add(name);continue
        if prepared.is_hidden_name(name):
            continue
        if an.is_token_var(name):
            entry={"type":name,"named":True}
            if name==root:entry["root"]=True
            if name in extras:entry["extra"]=True
            leaves.append(entry);seen_named.add(name);continue
        fields,children=an.node_info_for(name)
        entry={"type":name,"named":True}
        if name==root:entry["root"]=True
        if name in extras:entry["extra"]=True
        entry["fields"]=fields
        if children is not None:entry["children"]=children
        composite.append(entry);seen_named.add(name)
    # Named types introduced only via aliases: include as leaves/composites? Collect alias values named.
    alias_named=set()
    def collect_alias(expr):
        if isinstance(expr,dict):
            if expr.get("type")=="ALIAS" and expr.get("named") and expr.get("value"):alias_named.add(expr.get("value"))
            for v in expr.values():
                if isinstance(v,dict):collect_alias(v)
                elif isinstance(v,list):
                    for x in v:
                        if isinstance(x,dict):collect_alias(x)
    for e in (raw.get("rules") or {}).values():collect_alias(e)
    for nm in sorted(alias_named):
        if nm not in seen_named:
            leaves.append({"type":nm,"named":True})
    for typ in an.anonymous_types():
        anonymous.append({"type":typ,"named":False})
    composite.sort(key=lambda e:e["type"]);anonymous.sort(key=lambda e:e["type"]);leaves.sort(key=lambda e:e["type"])
    return composite+anonymous+leaves

def serialize_node_types(raw,prepared):
    return json.dumps(generate_node_types(raw,prepared),indent=2,ensure_ascii=False)
