def get_language_name_from_grammar_dir(grammar_dir):
    gpath=os.path.join(str(grammar_dir),"src","grammar.json")
    try:data=open(gpath,'rb').read()
    except OSError as e:raise TSErr(io_msg(e,gpath))
    try:
        jv=parse_json(data)
        if not isinstance(jv.value,dict):raise JsonError(f"invalid type: {jv.value}",jv.end_line,jv.end_col)
        if "name" not in jv.value:raise JsonError("missing field `name`",jv.end_line,jv.end_col)
        nv=jv.value["name"]
        if not isinstance(nv.value,str):raise JsonError(f"invalid type: {nv.value}, expected a string",nv.end_line,nv.end_col)
