    is_clang="clang" in os.path.basename(compiler)
    args=list(pre_args)
    if debug:args+=["-O0","-ffunction-sections","-fdata-sections","-fPIC","-g","-gdwarf-4","-fno-omit-frame-pointer"]
    else:args+=["-O2","-ffunction-sections","-fdata-sections","-fPIC"]
    if platform.machine() in ("x86_64","AMD64"):args+=["-m64"]
    if is_clang and platform.machine() in ("x86_64","AMD64"):args+=["--target=x86_64-unknown-linux-gnu"]
    args+=["-std=c11","-I",src_dir]
    cflags=os.environ.get("CFLAGS")
    if cflags:
        args+=shlex.split(cflags)
    else:
        args+=["-Wall"]
