    if debug and is_build_command:args+=["-DTREE_SITTER_DEBUG"]
    if reuse_allocator:args+=["-DTREE_SITTER_REUSE_ALLOCATOR"]
    args+=["-Werror=implicit-function-declaration","-shared","-Wl,--no-undefined"]
    sources=[os.path.join(src_dir,"parser.c")]
    scanner=os.path.join(src_dir,"scanner.c")
    if os.path.isfile(scanner):sources.append(scanner)
    args+=sources+["-o",str(output)]
    return compiler,args,sources

