from .edits import apply_edits
from .browser import open_browser_panic

def _duration_obj(seconds_float):
    secs=int(seconds_float);nanos=int(round((seconds_float-secs)*1_000_000_000))
    if nanos>=1_000_000_000:secs+=1;nanos-=1_000_000_000
    return {"secs":secs,"nanos":nanos}

def run_parse(parsed,prog):
    if parsed.values.get("json"):
        warn("--json is deprecated, use --json-summary instead")
        parsed.values["json_summary"]=True
    if parsed.values.get("wasm"):
        fail("--wasm flag specified, but this build of tree-sitter-cli does not include the wasm feature")
    loader,cfg=get_loader(parsed)
    # Debug graph / dot setup (create log.html, verify dot for -D)
    debug_graph=bool(parsed.values.get("debug_graph"));dot_flag=bool(parsed.values.get("dot"))
    log_path=os.path.join(os.getcwd(),"log.html")
    if debug_graph or dot_flag:
        try:
            with open(log_path,'w') as f:f.write("\n<!DOCTYPE html>\n\n<style>\nsvg { width: 100%; }\n</style>\n\n")
        except OSError as e:
            fail(io_msg(e))
        if debug_graph:
            # verify dot exists by trying to spawn it later; reference errors before parsing
            err=_check_dot()
            if err is not None:
                fail(TSErr("Failed to run the `dot` command. Check that graphviz is installed.",[err]))
    sources,is_stdin,test_entry=collect_sources(parsed)
    selector=LanguageSelector(loader,parsed)
    max_name_width=max((len(s.display) for s in sources if s.display),default=0)
    summaries=[];total_bytes=0;total_duration=0.0;success_count=0
    xml_sources=[]
    any_fail=False
    output_mode="sexp"
    if parsed.values.get("json_summary"):output_mode="json"
    elif dot_flag:output_mode="dot"
    elif parsed.values.get("xml"):output_mode="xml"
    elif parsed.values.get("cst"):output_mode="cst"
    for source in sources:
        data=read_source_data(source)
        lang=selector.language_for_source(source,data)
        text,enc=decode_source(data,parsed.values.get("encoding"))
        start_t=time.perf_counter()
        tree=parse_text(lang.prepared,text,data,enc)
        parse_duration=time.perf_counter()-start_t
        edit_duration=None;final_data=data;final_text=text
        edits=parsed.values.get("edits") or []
        if edits:
            try:
                final_data=apply_edits(data,edits)
            except TSErr as e:
                fail(e)
            final_text,enc2=decode_source(final_data,parsed.values.get("encoding") or enc)
            et=time.perf_counter();tree=parse_text(lang.prepared,final_text,final_data,enc2);edit_duration=time.perf_counter()-et
        root=tree.root if tree else None
        successful = root is not None and not root.has_error
        if successful:success_count+=1
        else:any_fail=True
        nbytes=len(final_data);total_bytes+=nbytes;total_duration+=parse_duration
        if parsed.values.get("debug"):
            _emit_debug_log(tree,final_text,parsed.values.get("debug"))
        # dot / debug graph output
        if debug_graph or dot_flag:
            graph=format_dot_graph(root,final_text)
            if dot_flag and not debug_graph:
                err=_run_dot_append(graph,log_path)
                if err is not None:
                    panic_unwrap("crates/cli/src/parse.rs:627:70","Failed to run the `dot` command. Check that graphviz is installed.",[err])
            else:
                err=_run_dot_append(graph,log_path)
                if err is not None:
                    fail(TSErr("Failed to run the `dot` command. Check that graphviz is installed.",[err]))
        if not parsed.values.get("quiet"):
            if output_mode=="sexp":
                sys.stdout.write(format_sexp(root,include_ranges=not parsed.values.get("no_ranges"))+"\n")
            elif output_mode=="cst":
                sys.stdout.write(format_cst(root,final_text))
            elif output_mode=="xml":
                xml_sources.append((source.display or "stdin",root,final_text))
            elif output_mode in ("dot","json"):
                pass
        # summaries for json
        summaries.append({
            "file":source.display if source.path is not None else None,
            "successful":successful,
            "start":{"row":root.start_point[0],"column":root.start_point[1]} if root else {"row":0,"column":0},
            "end":{"row":root.end_point[0],"column":root.end_point[1]} if root else {"row":0,"column":0},
            "duration":_duration_obj(parse_duration),
            "bytes":nbytes,
        })
        if parsed.values.get("time") or not successful:
            ms=parse_duration*1000.0
            bpm=int(nbytes/ms) if ms>0 else 0
            label=(source.display or "")
            line=f"{label:<{max_name_width}}\tParse:{ms:8.2f} ms\t{bpm:6} bytes/ms"
            if not successful and root is not None:
                errnode=smallest_error_node(root)
                if errnode is not None:line+=f"\t{format_error_summary_node(errnode)}"
            sys.stdout.write(line+"\n")
            if edits:
                ems=(edit_duration or 0)*1000.0
                sys.stdout.write(f"{'':<{max_name_width}}\tEdit:{ems:8.2f} ms\n")
    if output_mode=="xml" and not parsed.values.get("quiet"):
        sys.stdout.write(format_xml(xml_sources))
    if output_mode=="json":
        obj={
            "parse_summaries":summaries,
            "cumulative_stats":{"successful_parses":success_count,"total_parses":len(sources),"total_bytes":total_bytes,"total_duration":_duration_obj(total_duration)},
            "source_count":len(sources),
        }
        if not parsed.values.get("quiet"):
            sys.stdout.write(json.dumps(obj,indent=2,ensure_ascii=False)+"\n")
    elif parsed.values.get("stat"):
        total=len(sources);failed=total-success_count
        if total==0:
            sys.stdout.write("\nTotal parses: 0; successful parses: 0; failed parses: 0; success percentage: N/A; average speed: N/A\n\n")
        else:
            pct=success_count/total*100.0;avg=int(total_bytes/(total_duration*1000.0)) if total_duration>0 else 0
            sys.stdout.write(f"\nTotal parses: {total}; successful parses: {success_count}; failed parses: {failed}; success percentage: {pct:.2f}%; average speed: {avg} bytes/ms\n\n")
    if parsed.values.get("open_log") and debug_graph:
        open_browser_panic("file://"+log_path)
    return 1 if any_fail else 0

def _check_dot():
    try:
        p=subprocess.run(["dot","-Tsvg"],input=b"digraph{}",capture_output=True)
        return None
    except OSError as e:
        return io_msg(e)

def _run_dot_append(graph,log_path):
    try:
        p=subprocess.run(["dot","-Tsvg"],input=graph.encode(),capture_output=True)
    except OSError as e:
        return io_msg(e)
    try:
        with open(log_path,'ab') as f:f.write(p.stdout)
    except OSError as e:return io_msg(e)
    return None

def _emit_debug_log(tree,text,mode):
    if mode=="quiet" or tree is None:return
    pretty=(mode=="pretty")
    lines=[]
    lines.append("new_parse")
    # token-level log from leaf tokens
    tokens=[]
    def collect(n):
        if not n.children:
            if not n.is_missing:tokens.append(n)
            return
        for c in n.children:collect(c.node)
    collect(tree.root)
    state=1;pos=0
    for tok in tokens:
        lines.append(f"process version:0, version_count:1, state:{state}, row:{tok.start_point[0]}, col:{tok.start_point[1]}")
        lines.append(f"lex_internal state:0, row:{tok.start_point[0]}, column:{tok.start_point[1]}")
        # skipped chars from pos to tok.start
        for i in range(pos,tok.start):
            ch=text[i]
            lines.append(f"  skip character:{_char_repr(ch)}")
        for i in range(tok.start,tok.end):
            lines.append(f"  consume character:{_char_repr(text[i])}")
        sym=tok.kind
        lines.append(f"lexed_lookahead sym:{sym}, size:{tok.end-max(pos,tok.start) if False else tok.end-pos}")
        pos=tok.end;state+=1
        if tok.is_extra:lines.append("shift_extra")
        else:lines.append(f"shift state:{state}")
    lines.append(f"process version:0, version_count:1, state:{state}, row:{tree.root.end_point[0]}, col:{tree.root.end_point[1]}")
    lines.append("accept")
    for line in lines:
        if pretty:
            if line.startswith("  "):sys.stderr.write(f"  \x1b[37m{line[2:]}\x1b[0m\n")
            else:sys.stderr.write(f"\x1b[37m{line}\x1b[0m\n")
        else:sys.stderr.write(line+"\n")

def _char_repr(ch):
    if ch=='\n':return "10"
    if ch=='\r':return "13"
    if ch=='\t':return "9"
    return f"'{ch}'"
