import os, sys, shlex, shutil, subprocess
from .errors import panic

KNOWN_BROWSERS=["firefox","mozilla","google-chrome","google-chrome-stable","chromium","chromium-browser","brave","brave-browser","opera","vivaldi","epiphany","konqueror","safari","microsoft-edge","msedge"]

def _try_browser_command(cmd,url):
    try:
        parts=shlex.split(cmd)
    except Exception:return False
    if not parts:return False
    exe=parts[0]
    if shutil.which(exe) is None and not os.path.isfile(exe):return False
    args=[]
    replaced=False
    for p in parts[1:]:
        if "%s" in p:args.append(p.replace("%s",url));replaced=True
        else:args.append(p)
    if "%s" in exe:exe=exe.replace("%s",url);replaced=True
    if not replaced:args.append(url)
    try:
        subprocess.Popen([exe]+args,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
        return True
    except OSError:
        return False

def open_browser(url):
    browser=os.environ.get("BROWSER")
    if browser:
        for cmd in browser.split(":"):
            if cmd and _try_browser_command(cmd,url):return True
        return False
    for name in KNOWN_BROWSERS:
        if shutil.which(name):
            return _try_browser_command(name,url)
    return False

def open_browser_panic(url):
    if not open_browser(url):
        panic("crates/cli/src/util.rs:121:64",'called `Result::unwrap()` on an `Err` value: Custom { kind: NotFound, error: "No valid browsers detected. You can specify one in BROWSER environment variable" }')
