from .errors import TSErr

def _parse_usize(s):
    if s=="":raise ValueError()
    t=s[1:] if s.startswith("+") else s
    if not t or any(not c.isdigit() or not c.isascii() for c in t):raise ValueError()
    v=int(t)
    if v>18446744073709551615:raise ValueError()
    return v

def parse_edit(s):
    err=TSErr(f"Invalid edit string '{s}'. Edit strings must match the pattern '<START_BYTE_OR_POSITION> <REMOVED_LENGTH> <NEW_TEXT>'")
    first=s.find(' ')
    if first<=0:raise err
    pos_str=s[:first];rest=s[first+1:]
    second=rest.find(' ')
    if second==-1:del_str=rest;insert=""
    else:del_str=rest[:second];insert=rest[second+1:]
    if del_str=="":raise err
    try:del_count=_parse_usize(del_str)
    except ValueError:raise err
    if ',' in pos_str:
        parts=pos_str.split(',')
        if len(parts)<2:raise err
        try:row=_parse_usize(parts[0]);col=_parse_usize(parts[1])
        except ValueError:raise err
        return ('rowcol',row,col,del_count,insert)
    try:byte=_parse_usize(pos_str)
    except ValueError:raise err
    return ('byte',byte,del_count,insert)

def resolve_rowcol(data,row,col):
    if len(data)==0:
        if row>0:raise TSErr(f"Failed to address a row: {row}")
        return col+1
    segments=data.split(b'\n')
    if row>=len(segments):raise TSErr(f"Failed to address a row: {row}")
    starts=[];off=0
    for seg in segments:starts.append(off);off+=len(seg)+1
    start=starts[row]+col+(1 if row==0 else 0)
    if row+1<len(segments):max_off=starts[row+1]+len(segments[row+1])
    else:max_off=len(data)
    if start>max_off:
        if row+1<len(segments)-1:
            raise TSErr(f"Failed to address a column: {col}")
        raise TSErr("Failed to address a column over the end")
    return start

def apply_edits(data,edit_strings):
    data=bytearray(data)
    for s in edit_strings:
        e=parse_edit(s)
        if e[0]=='byte':
            _,start,del_count,insert=e
