    if shutil.which(exe) is None and not os.path.isfile(exe):return False
    args=[]
    replaced=False
    for p in parts[1:]:
        if "%s" in p:args.append(p.replace("%s",url));replaced=True
        else:args.append(p)
    if "%s" in exe:exe=exe.replace("%s",url);replaced=True
    if not replaced:args.append(url)
    try:
        subprocess.Popen([exe]+args,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
        return True
    except OSError:
        return False

