def _validate_grammar(grammar):
    rules=grammar.get("rules") or {}
    externals=set()
    for ex in grammar.get("externals") or []:
        if isinstance(ex,dict) and ex.get("type")=="SYMBOL":externals.add(ex.get("name"))
