            raise TSErr("The rule `` matches the empty string.\nTree-sitter does not support syntactic rules that match the empty string\nunless they are used only as the grammar's start rule.\n")
        for v in expr.values():
            if isinstance(v,dict):walk(v,parent)
            elif isinstance(v,list):
                for x in v:
                    if isinstance(x,dict):walk(x,parent)
    for name,expr in rules.items():walk(expr,name)
    for ex in grammar.get("extras") or []:walk(ex,None)
