        cnt=[0]
        def check_repeat(e):
            if not isinstance(e,dict):return
            if e.get("type") in ("REPEAT","REPEAT1"):
                cnt[0]+=1
                if _expr_nullable(e.get("content"),nullable):
                    raise TSErr(f"The rule `{name}_repeat{cnt[0]}` matches the empty string.\n\nTree-sitter does not support syntactic rules that match the empty string\nunless they are used only as the grammar's start rule.\n")
            for v in e.values():
                if isinstance(v,dict):check_repeat(v)
                elif isinstance(v,list):
                    for x in v:
                        if isinstance(x,dict):check_repeat(x)
        check_repeat(expr)
    for name in rules:
        if name!=root and nullable.get(name):
            # token (pattern) rules may match empty in practice; only flag syntactic seq/choice/blank rules
            expr=rules[name]
            if isinstance(expr,dict) and expr.get("type") in ("BLANK",):
                raise TSErr(f"The rule `{name}` matches the empty string.\nTree-sitter does not support syntactic rules that match the empty string\nunless they are used only as the grammar's start rule.\n")

def _contains_symbol(expr,name):
    if isinstance(expr,dict):
        if expr.get("type")=="SYMBOL" and expr.get("name")==name:return True
        return any(_contains_symbol(v,name) for v in expr.values() if isinstance(v,(dict,list)))
    if isinstance(expr,list):return any(_contains_symbol(x,name) for x in expr)
    return False

def _nullable_rules(grammar):
    rules=grammar.get("rules") or {};nullable={n:False for n in rules}
