            if parsed.values.get("captures"):
                for m,cap in eng.captures_in_order(matches):
                    idx,name,node=cap
                    sys.stdout.write(f"  pattern: {m.pattern_index}\n")
                    sys.stdout.write(f"    capture: {idx} - {name}, start: ({node.start_point[0]}, {node.start_point[1]}), end: ({node.end_point[0]}, {node.end_point[1]}), text: `{text[node.start:node.end]}`\n")
            else:
                for m in matches:
                    sys.stdout.write(f"  pattern: {m.pattern_index}\n")
                    for idx,name,node in m.captures:
                        sys.stdout.write(f"    capture: {idx} - {name}, start: ({node.start_point[0]}, {node.start_point[1]}), end: ({node.end_point[0]}, {node.end_point[1]}), text: `{text[node.start:node.end]}`\n")
        if parsed.values.get("time"):
            ms=(time.perf_counter()-start)*1000
            label=source.display or "stdin"
            sys.stdout.write(f"{label}\t{ms:.2f} ms\n")
    return 0
