import os,re
from .query_engine import parse_query_text, QueryEngine, QueryError
from .errors import TSErr, warn

class Style:
    def __init__(self,color=None,bold=False,italic=False,underline=False):
        self.color=color;self.bold=bold;self.italic=italic;self.underline=underline
    def __repr__(self):return f"Style({self.color},{self.bold},{self.italic},{self.underline})"

CSS_COLORS={
 'black':(0,0,0),'silver':(192,192,192),'gray':(128,128,128),'white':(255,255,255),'maroon':(128,0,0),'red':(255,0,0),'purple':(128,0,128),'fuchsia':(255,0,255),'green':(0,128,0),'lime':(0,255,0),'olive':(128,128,0),'yellow':(255,255,0),'navy':(0,0,128),'blue':(0,0,255),'teal':(0,128,128),'aqua':(0,255,255),'orange':(255,165,0),'brown':(165,42,42),'pink':(255,192,203),'magenta':(255,0,255),'cyan':(0,255,255),'grey':(128,128,128),
}

def parse_color(v):
    if isinstance(v,int):return ('fixed',v)
    if isinstance(v,(list,tuple)) and len(v)>=3:return ('rgb',(int(v[0]),int(v[1]),int(v[2])))
    if isinstance(v,str):
        s=v.strip().lower()
        if s in CSS_COLORS:return ('rgb',CSS_COLORS[s])
        if s.startswith('#'):
            h=s[1:]
            if len(h)==3:h=''.join(c*2 for c in h)
            if len(h)==6:
                try:return ('rgb',(int(h[0:2],16),int(h[2:4],16),int(h[4:6],16)))
                except:return None
        m=re.match(r'rgb\((\d+),\s*(\d+),\s*(\d+)\)',s)
        if m:return ('rgb',tuple(int(x) for x in m.groups()))
    return None

def parse_style(v):
    if v is None:return Style(None)
    if isinstance(v,dict):
        return Style(parse_color(v.get('color')) if 'color' in v else None,bool(v.get('bold',False)),bool(v.get('italic',False)),bool(v.get('underline',False)))
    return Style(parse_color(v))

def ansi_prefix(style):
    if style is None:return ""
    out=""
    if style.bold:out+="\x1b[1m"
    if style.italic:out+="\x1b[3m"
    if style.underline:out+="\x1b[4m"
    if style.color:
        kind,val=style.color
        if kind=='fixed':out+=f"\x1b[38;5;{val}m"
        elif kind=='rgb':out+=f"\x1b[38;2;{val[0]};{val[1]};{val[2]}m"
    return out

