import re

class SexpNode:
    def __init__(self,name,children=None,is_missing=False,missing_anon=False,rng=None,named=True):
        self.name=name;self.children=children or [];self.is_missing=is_missing;self.missing_anon=missing_anon;self.rng=rng;self.named=named

def tree_to_sexp(node):
    if node.is_missing:
        return SexpNode(node.kind,[],True,missing_anon=not node.named,rng=(node.start_point,node.end_point),named=node.named)
    children=[]
    for c in node.children:
        if c.node.named or c.node.is_missing:
            children.append((c.field,tree_to_sexp(c.node)))
    return SexpNode(node.kind,children,rng=(node.start_point,node.end_point),named=node.named)

def _tokenize(text):
    toks=[];i=0;n=len(text)
    while i<n:
        ch=text[i]
        if ch.isspace():i+=1;continue
        if ch in '()':toks.append(ch);i+=1;continue
        if ch=='"':
            j=i+1;out=[]
            while j<n:
                if text[j]=='\\' and j+1<n:out.append(text[j+1]);j+=2;continue
                if text[j]=='"':break
                out.append(text[j]);j+=1
            toks.append(('str',"".join(out)));i=j+1;continue
        j=i
        while j<n and not text[j].isspace() and text[j] not in '()':j+=1
        toks.append(text[i:j]);i=j
    return toks

class _Parser:
    def __init__(self,toks):self.toks=toks;self.i=0
    def parse(self):
        if self.i>=len(self.toks):return None
        return self.parse_node()
    def parse_node(self):
        if self.i>=len(self.toks):return None
        t=self.toks[self.i]
        if t!='(':
            return None
        self.i+=1
        if self.i>=len(self.toks):return SexpNode("")
        name_tok=self.toks[self.i];self.i+=1
        if isinstance(name_tok,tuple):name=name_tok[1]
        else:name=name_tok
        if name=="MISSING":
            # next atom/string is kind
            if self.i<len(self.toks):
                kt=self.toks[self.i];self.i+=1
                if isinstance(kt,tuple):return SexpNode(kt[1],[],True,missing_anon=True,named=False)
                return SexpNode(kt,[],True,named=True)
            return SexpNode("",[],True)
        node=SexpNode(name)
        # optional range [r, c] - [r, c]
        rng=self._try_range()
        if rng:node.rng=rng
        field=None
        while self.i<len(self.toks) and self.toks[self.i]!=')':
            tok=self.toks[self.i]
            if tok=='(':
                child=self.parse_node()
                if child is not None:node.children.append((field,child))
                field=None;continue
            if isinstance(tok,tuple):
                # anonymous string child
                node.children.append((field,SexpNode(tok[1],named=False)));field=None;self.i+=1;continue
            if isinstance(tok,str) and tok.endswith(':') and len(tok)>1:
                field=tok[:-1];self.i+=1;continue
            # bare atoms ignored
            self.i+=1
        if self.i<len(self.toks) and self.toks[self.i]==')':self.i+=1
        return node
    def _try_range(self):
        # tokens like [0, 0] - [0, 5]
        save=self.i
        def get():
            if self.i>=len(self.toks):return None
            t=self.toks[self.i];self.i+=1;return t
        try:
            t1=get()
            if not (isinstance(t1,str) and t1.startswith('[')):raise ValueError()
            # collect until ] token across up to 2 toks
            parts=[t1]
            while not parts[-1].endswith(']'):
                parts.append(get())
            if get()!='-':raise ValueError()
            t2=get();parts2=[t2]
            while not parts2[-1].endswith(']'):parts2.append(get())
            def parse_point(ps):
