_orig_parse=_Parser.parse_node

def format_sexp_node(node,include_fields=True,include_ranges=False):
    if node is None:return ")"
    def fmt(n,depth):
        if n.is_missing:
            inner=f'"{n.name}"' if n.missing_anon else n.name
            return f"(MISSING {inner})"
        head=f"({n.name}"
        if include_ranges and n.rng:head+=f" [{n.rng[0][0]}, {n.rng[0][1]}] - [{n.rng[1][0]}, {n.rng[1][1]}]"
        if not n.children:return head+")"
        lines=[head]
        for field,child in n.children:
            child_fmt=fmt(child,depth+1)
            lines.append("  "*(depth+1)+(f"{field}: " if include_fields and field else "")+child_fmt.split("\n")[0])
            lines.extend(child_fmt.split("\n")[1:])
        return "\n".join(lines)+")"
    return fmt(node,0)

def format_sexp_node_compact(node,include_fields=True,include_ranges=False):
    if node is None:return ")"
    if node.is_missing:
        inner=f'"{node.name}"' if node.missing_anon else node.name;return f"(MISSING {inner})"
    if not node.children:return f"({node.name})"
    inner=" ".join(((f"{f}: " if include_fields and f else "")+format_sexp_node_compact(c,include_fields,include_ranges)) for f,c in node.children)
    return f"({node.name} {inner})"
