def _dur(sec):
    s=int(sec);n=int(round((sec-s)*1_000_000_000))
    if n>=1_000_000_000:s+=1;n-=1_000_000_000
    return {"secs":s,"nanos":n}

def _stats_line(total,successful,total_bytes,total_duration):
    failed=total-successful
    if total==0:return "\nTotal parses: 0; successful parses: 0; failed parses: 0; success percentage: N/A; average speed: N/A\n\n"
    pct=successful/total*100.0;avg=int(total_bytes/(total_duration*1000.0)) if total_duration>0 else 0
    return f"\nTotal parses: {total}; successful parses: {successful}; failed parses: {failed}; success percentage: {pct:.2f}%; average speed: {avg} bytes/ms\n\n"

def _group_json(g):
    children=[]
    for ch in g.get("children",[]):
        if "test" in ch:
            outcome=ch.get("outcome")
            if outcome=="Updated":outcome="Failed"
            children.append({"name":ch["name"],"outcome":outcome,"parse_rate":ch.get("parse_rate"),"test_num":ch["test"].test_num})
        else:children.append(_group_json(ch))
    return {"name":g["name"],"children":children}

def _print_group(g,depth,stat_mode,is_outlier):
    indent="  "*(depth+1)
