    for ch in g.get("children",[]):
        if "test" in ch:
            outcome=ch.get("outcome");num=ch["test"].test_num
            stat=""
            if stat_mode=="all" and ch.get("parse_rate") is not None:stat=f" ({ch['parse_rate']:.3f} bytes/ms)"
            elif stat_mode=="outliers-and-total" and is_outlier(ch.get("parse_rate")):stat=f" ({ch['parse_rate']:.3f} bytes/ms)"
            leaf_indent="  "*(depth+3)
            if outcome=="Passed":sys.stdout.write(f"{leaf_indent}{num}. ✓ \x1b[32m{ch['name']}\x1b[0m{stat}\n")
            elif outcome=="Failed":sys.stdout.write(f"{leaf_indent}{num}. ✗ \x1b[31m{ch['name']}\x1b[0m{stat}\n")
            elif outcome=="Updated":sys.stdout.write(f"{leaf_indent}{num}. ✓ \x1b[34m{ch['name']}\x1b[0m{stat}\n")
            elif outcome=="Skipped":sys.stdout.write(f"{leaf_indent}{num}. ⌀ \x1b[33m{ch['name']}\x1b[0m{stat}\n")
            elif outcome=="Platform":sys.stdout.write(f"{leaf_indent}{num}. ⌀ \x1b[35m{ch['name']}\x1b[0m{stat}\n")
            else:sys.stdout.write(f"{leaf_indent}{num}. ? {ch['name']}\n")
        else:_print_group(ch,depth+1,stat_mode,is_outlier)

def _diff_pretty(actual,expected):
    # Indent every line by 4 spaces (reference indents the formatted trees)
    def ind(s):return "\n".join("    "+l if l else l for l in s.split("\n"))
    a_lines=ind(actual).splitlines(True);e_lines=ind(expected).splitlines(True)
    # splitlines(True) drops a trailing newline distinction; ensure last lines have no newline as in reference
    out=[]
    sm=difflib.SequenceMatcher(None,[l.rstrip('\n') for l in a_lines],[l.rstrip('\n') for l in e_lines])
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag in ("equal","replace","delete"):
            for l in a_lines[i1:i2]:
                if tag=="equal":out.append(l if l.endswith("\n") else l+"\n")
                else:out.append("\x1b[31m"+l+"\x1b[0m"+("" if l.endswith("\n") else "\n"))
        if tag in ("replace","insert"):
            for l in e_lines[j1:j2]:out.append("\x1b[32m"+l+"\x1b[0m"+("" if l.endswith("\n") else "\n"))
    return "".join(out)

def _run_assertion_sections(loader,cfg,root,parsed,get_language_fallback=None):
    """Run test/highlight and test/tags. Returns (json-like dict, failure_count). Results are also stored for printing."""
    result={"sections":[]}
    json_res={"highlight":[],"tags":[],"query":[]};fail_count=0
    theme=load_theme(cfg)
    for kind,dirname,title in (("highlight","highlight","syntax highlighting"),("tags","tags","tags")):
        base=os.path.join(str(root),"test",dirname)
        if not os.path.isdir(base):continue
        files=[]
        for r,dirs,fs in os.walk(base):
            dirs.sort()
            for fn in sorted(fs):files.append(os.path.join(r,fn))
        if not files:continue
        entries=[]
        for fp in files:
            rel=os.path.relpath(fp,base)
            data=open(fp,'rb').read();text=data.decode('utf-8','surrogateescape')
            cfgobj=loader.find_for_path(fp,data)
            lang=None
            if cfgobj is not None:
                try:lang=loader.load_language_for_config(cfgobj,rebuild=bool(parsed.values.get("rebuild") or parsed.values.get("grammar_path")),debug_build=bool(parsed.values.get("debug_build")))
                except TSErr:lang=None
            if lang is None:
                continue
            tree=parse_text(lang.prepared,text,data)
            if kind=="highlight":
                config=load_highlight_config_for_language(lang,loader)
                if config is None:continue
                ok,msg,count=run_highlight_assertions(lang,tree,text,config,theme)
            else:
                from .tags_cmd import _resolve_query
                tags_q=_resolve_query(cfgobj,cfgobj.tags if cfgobj else None,"tags.scm",lang.parser_path)
                locals_q=_resolve_query(cfgobj,cfgobj.locals if cfgobj else None,"locals.scm",lang.parser_path)
                if not tags_q:continue
                ok,msg,count=run_tags_assertions(lang,tree,text,tags_q,locals_q)
            if not ok:fail_count+=1
            entries.append({"name":rel,"outcome":"Passed" if ok else "Failed","message":msg,"count":count})
            json_res[kind].append({"name":os.path.splitext(os.path.basename(fp))[0],"children":[{"name":rel,"outcome":"Passed" if ok else "Failed","parse_rate":None,"test_num":len(entries)}]})
        if entries:result["sections"].append((title,entries))
    result["_json"]=json_res
    # stash for printer via global-ish attribute on dict subclass would be lost; encode sections into json_res return via closure in caller by attaching to a list object
    _run_assertion_sections.last=result
    return json_res,fail_count

def _print_assertion_sections(json_res):
    result=getattr(_run_assertion_sections,'last',{"sections":[]})
    for title,entries in result.get("sections",[]):
        sys.stdout.write(f"\n{title}:\n")
        for i,e in enumerate(entries,1):
            if e["outcome"]=="Passed":sys.stdout.write(f"      {i}. ✓ \x1b[32m{e['name']}\x1b[0m ({e['count']} assertions)\n")
            else:
                sys.stdout.write(f"      {i}. ✗ \x1b[31m{e['name']}\x1b[0m\n")
                if e.get("message"):sys.stdout.write(e["message"]+"\n")
