            expected_pretty=format_sexp_node(exp_node,include_fields=include_fields,include_ranges=exp_has_ranges)
            passed=(actual_pretty==expected_pretty)
            expected_for_fail=expected_pretty
            if "error" in test.attrs and not tree.root.has_error:
                passed=False;expected_for_fail="NO ERROR"
            fail_actual=format_sexp_node_compact(actual_node,include_fields=include_fields)
            fail_expected=expected_for_fail if expected_for_fail=="NO ERROR" else format_sexp_node_compact(exp_node,include_fields=include_fields)
            fail_expected_pretty=expected_for_fail;fail_actual_pretty=actual_pretty
            new_expected=actual_pretty
        if passed:
            leaf["outcome"]="Passed";successful+=1
        else:
            if update_mode:
                leaf["outcome"]="Updated";updates.append(test.name);file_updates.setdefault(test.path,[]).append((test,new_expected))
            else:
                leaf["outcome"]="Failed"
                failures.append({"name":test.name,"actual":fail_actual,"expected":fail_expected,"actual_pretty":fail_actual_pretty,"expected_pretty":fail_expected_pretty,"is_cst":is_cst})
    # apply updates
    if update_mode and file_updates:
        for path,ups in file_updates.items():
            try:content=open(path,encoding='utf-8',errors='surrogateescape').read()
            except OSError as e:fail(io_msg(e))
            # apply from last span to first
            for test,new_exp in sorted(ups,key=lambda x:x[0].expected_span[0],reverse=True):
                start,end=test.expected_span;old=content[start:end]
                lead_len=len(old)-len(old.lstrip());trail_len=len(old)-len(old.rstrip())
                lead=old[:lead_len];trail=old[len(old)-trail_len:] if trail_len else ""
                # If old was all whitespace, lead is that whitespace; simplify to a single leading newline
                if old.strip()=="":lead="\n";trail=""
                content=content[:start]+lead+new_exp+trail+content[end:]
            try:open(path,'w',encoding='utf-8').write(content)
            except OSError as e:fail(io_msg(e))
    # highlight / tags test sections
    hl_results,hl_fail_count=_run_assertion_sections(loader,cfg,root,parsed,get_language_fallback=(lib_lang or (get_language() if configs or lib_lang else None)))
    # overview printing order in non-json mode: corpus overview, failures/updates, then highlight/tag sections were already run but printed below.
    stat_mode=parsed.values.get("stat")
    # compute outlier rates if needed
    rates=[]
    def collect_rates(g):
        for ch in g.get("children",[]):
            if "test" in ch and ch.get("parse_rate") is not None:rates.append(ch["parse_rate"])
            if "children" in ch and "test" not in ch:collect_rates(ch)
    collect_rates(root_group)
    def is_outlier(rate):
        if len(rates)<2 or rate is None:return False
        mean=sum(rates)/len(rates);var=sum((r-mean)**2 for r in rates)/len(rates);sd=var**0.5
        return rate < mean-sd
    if json_mode:
        obj={
            "parse_results":[_group_json(g) for g in root_group["children"]],
            "parse_failures":[{"name":f["name"],"actual":f["actual"],"expected":f["expected"],"is_cst":f["is_cst"]} for f in failures],
            "parse_stats":{"successful_parses":successful,"total_parses":total,"total_bytes":total_bytes,"total_duration":_dur(total_duration)},
            "highlight_results":hl_results.get("highlight",[]),
            "tag_results":hl_results.get("tags",[]),
            "query_results":hl_results.get("query",[]),
        }
        sys.stdout.write(json.dumps(obj,indent=2,ensure_ascii=False)+"\n")
    else:
        for g in root_group["children"]:_print_group(g,0,stat_mode,is_outlier)
        if not parsed.values.get("overview_only"):
            if failures:
                sys.stdout.write(f"\n{len(failures)} failure{'s' if len(failures)!=1 else ''}:\n\n")
                sys.stdout.write("correct / \x1b[32mexpected\x1b[0m / \x1b[31munexpected\x1b[0m\n")
                for i,f in enumerate(failures,1):
                    sys.stdout.write(f"  {i}. {f['name']}:\n\n")
                    sys.stdout.write(_diff_pretty(f["actual_pretty"],f["expected_pretty"]))
                    sys.stdout.write("\n")
            if updates:
                sys.stdout.write(f"\n{len(updates)} update{'s' if len(updates)!=1 else ''}:\n\n")
                for i,nm in enumerate(updates,1):sys.stdout.write(f"  {i}. {nm}\n")
        _print_assertion_sections(hl_results)
        sys.stdout.write(_stats_line(total,successful,total_bytes,total_duration))
    if parsed.values.get("open_log") and parsed.values.get("debug_graph"):
        from .browser import open_browser_panic;open_browser_panic("file://"+os.path.join(os.getcwd(),"log.html"))
    if language_error:
        fail(language_error)
    if hl_fail_count:return 1
    return 0 if (not failures or update_mode) else 1

def _dur(sec):
    s=int(sec);n=int(round((sec-s)*1_000_000_000))
    if n>=1_000_000_000:s+=1;n-=1_000_000_000
    return {"secs":s,"nanos":n}

def _stats_line(total,successful,total_bytes,total_duration):
    failed=total-successful
    if total==0:return "\nTotal parses: 0; successful parses: 0; failed parses: 0; success percentage: N/A; average speed: N/A\n\n"
    pct=successful/total*100.0;avg=int(total_bytes/(total_duration*1000.0)) if total_duration>0 else 0
    return f"\nTotal parses: {total}; successful parses: {successful}; failed parses: {failed}; success percentage: {pct:.2f}%; average speed: {avg} bytes/ms\n\n"

def _group_json(g):
    children=[]
    for ch in g.get("children",[]):
        if "test" in ch:
            outcome=ch.get("outcome")
            if outcome=="Updated":outcome="Failed"
            children.append({"name":ch["name"],"outcome":outcome,"parse_rate":ch.get("parse_rate"),"test_num":ch["test"].test_num})
        else:children.append(_group_json(ch))
    return {"name":g["name"],"children":children}

def _print_group(g,depth,stat_mode,is_outlier):
    indent="  "*(depth+1)
    sys.stdout.write(f"{indent}{g['name']}:\n")
    for ch in g.get("children",[]):
        if "test" in ch:
            outcome=ch.get("outcome");num=ch["test"].test_num
            stat=""
            if stat_mode=="all" and ch.get("parse_rate") is not None:stat=f" ({ch['parse_rate']:.3f} bytes/ms)"
            elif stat_mode=="outliers-and-total" and is_outlier(ch.get("parse_rate")):stat=f" ({ch['parse_rate']:.3f} bytes/ms)"
            leaf_indent="  "*(depth+3)
            if outcome=="Passed":sys.stdout.write(f"{leaf_indent}{num}. ✓ \x1b[32m{ch['name']}\x1b[0m{stat}\n")
            elif outcome=="Failed":sys.stdout.write(f"{leaf_indent}{num}. ✗ \x1b[31m{ch['name']}\x1b[0m{stat}\n")
            elif outcome=="Updated":sys.stdout.write(f"{leaf_indent}{num}. ✓ \x1b[34m{ch['name']}\x1b[0m{stat}\n")
            elif outcome=="Skipped":sys.stdout.write(f"{leaf_indent}{num}. ⌀ \x1b[33m{ch['name']}\x1b[0m{stat}\n")
            elif outcome=="Platform":sys.stdout.write(f"{leaf_indent}{num}. ⌀ \x1b[35m{ch['name']}\x1b[0m{stat}\n")
            else:sys.stdout.write(f"{leaf_indent}{num}. ? {ch['name']}\n")
        else:_print_group(ch,depth+1,stat_mode,is_outlier)

def _diff_pretty(actual,expected):
    # Indent every line by 4 spaces (reference indents the formatted trees)
    def ind(s):return "\n".join("    "+l if l else l for l in s.split("\n"))
    a_lines=ind(actual).splitlines(True);e_lines=ind(expected).splitlines(True)
    # splitlines(True) drops a trailing newline distinction; ensure last lines have no newline as in reference
    out=[]
    sm=difflib.SequenceMatcher(None,[l.rstrip('\n') for l in a_lines],[l.rstrip('\n') for l in e_lines])
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag in ("equal","replace","delete"):
            for l in a_lines[i1:i2]:
                if tag=="equal":out.append(l if l.endswith("\n") else l+"\n")
                else:out.append("\x1b[31m"+l+"\x1b[0m"+("" if l.endswith("\n") else "\n"))
        if tag in ("replace","insert"):
            for l in e_lines[j1:j2]:out.append("\x1b[32m"+l+"\x1b[0m"+("" if l.endswith("\n") else "\n"))
    return "".join(out)

def _run_assertion_sections(loader,cfg,root,parsed,get_language_fallback=None):
    """Run test/highlight and test/tags. Returns (json-like dict, failure_count). Results are also stored for printing."""
    result={"sections":[]}
    json_res={"highlight":[],"tags":[],"query":[]};fail_count=0
    theme=load_theme(cfg)
    for kind,dirname,title in (("highlight","highlight","syntax highlighting"),("tags","tags","tags")):
        base=os.path.join(str(root),"test",dirname)
        if not os.path.isdir(base):continue
        files=[]
        for r,dirs,fs in os.walk(base):
            dirs.sort()
            for fn in sorted(fs):files.append(os.path.join(r,fn))
        if not files:continue
        entries=[]
        for fp in files:
            rel=os.path.relpath(fp,base)
            data=open(fp,'rb').read();text=data.decode('utf-8','surrogateescape')
            cfgobj=loader.find_for_path(fp,data)
            lang=None
            if cfgobj is not None:
                try:lang=loader.load_language_for_config(cfgobj,rebuild=bool(parsed.values.get("rebuild") or parsed.values.get("grammar_path")),debug_build=bool(parsed.values.get("debug_build")))
                except TSErr:lang=None
            if lang is None:
                continue
            tree=parse_text(lang.prepared,text,data)
            if kind=="highlight":
                config=load_highlight_config_for_language(lang,loader)
                if config is None:continue
                ok,msg,count=run_highlight_assertions(lang,tree,text,config,theme)
            else:
                from .tags_cmd import _resolve_query
                tags_q=_resolve_query(cfgobj,cfgobj.tags if cfgobj else None,"tags.scm",lang.parser_path)
                locals_q=_resolve_query(cfgobj,cfgobj.locals if cfgobj else None,"locals.scm",lang.parser_path)
                if not tags_q:continue
                ok,msg,count=run_tags_assertions(lang,tree,text,tags_q,locals_q)
            if not ok:fail_count+=1
            entries.append({"name":rel,"outcome":"Passed" if ok else "Failed","message":msg,"count":count})
            json_res[kind].append({"name":os.path.splitext(os.path.basename(fp))[0],"children":[{"name":rel,"outcome":"Passed" if ok else "Failed","parse_rate":None,"test_num":len(entries)}]})
        if entries:result["sections"].append((title,entries))
    result["_json"]=json_res
    # stash for printer via global-ish attribute on dict subclass would be lost; encode sections into json_res return via closure in caller by attaching to a list object
    _run_assertion_sections.last=result
    return json_res,fail_count

def _print_assertion_sections(json_res):
    result=getattr(_run_assertion_sections,'last',{"sections":[]})
    for title,entries in result.get("sections",[]):
        sys.stdout.write(f"\n{title}:\n")
        for i,e in enumerate(entries,1):
            if e["outcome"]=="Passed":sys.stdout.write(f"      {i}. ✓ \x1b[32m{e['name']}\x1b[0m ({e['count']} assertions)\n")
            else:
                sys.stdout.write(f"      {i}. ✗ \x1b[31m{e['name']}\x1b[0m\n")
                if e.get("message"):sys.stdout.write(e["message"]+"\n")
