    # our _prompt_text already printed the entered (empty) value, so fix it
    # by rewriting the previous line when it differs.
    label=_last_prompt_info.get('label')
    if label and not inp:
        sys.stderr.write(f"\x1b[1A\r\x1b[2K✔ {label} · {display}\r\n")

def _set_cbreak(fd):
    import termios, tty
    old=termios.tcgetattr(fd);tty.setcbreak(fd);return old

def _restore(fd,old):
    import termios
    termios.tcsetattr(fd,termios.TCSADRAIN,old)

def _read_key():
    b=os.read(0,1)
    if not b:return ''
    if b==b'\x1b':
        seq=b+os.read(0,2)
        return seq.decode('utf-8','replace')
    # decode one utf-8 char
    if b[0]>=0xC0:
        need=1 if b[0]<0xE0 else 2 if b[0]<0xF0 else 3
        b+=os.read(0,need)
    return b.decode('utf-8','surrogateescape')

def _prompt_text(label,default=None,required=False):
    _last_prompt_info['label']=label
    prompt_label=f"{label} ({default})" if default else label
    while True:
        sys.stderr.write(f"? {prompt_label} › ");sys.stderr.flush()
        try:old=_set_cbreak(0)
        except Exception:old=None
        chars=[]
        try:
            while True:
