            if key in ('n','N'):
                sys.stderr.write(f"\r\x1b[2K✔ {label} · no\r\n"+"\x1b[?25h");return False
            if key=='\x03':raise KeyboardInterrupt()
    finally:
        if old is not None:_restore(0,old)
