        finally:
            if old is not None:_restore(0,old)
        value="".join(chars)
        if required and not value:
            sys.stderr.write("\r\x1b[2K");continue
        display=value if value else (default or "")
        sys.stderr.write(f"\r\x1b[2K✔ {label} · {display}\r\n")
        return value

def _prompt_bindings():
    options=["c","go","java","node","python","rust","swift","zig"]
    selected=[True,True,False,True,True,True,True,False]
    cursor=0
    sys.stderr.write("\x1b[?25l")
    def render(first=False):
        lines=["Bindings:"]
        for i,opt in enumerate(options):
            lines.append(f"{'>' if i==cursor else ' '} [{'x' if selected[i] else ' '}] {opt}")
        lines.append("")
        if not first:
            sys.stderr.write(f"\x1b[{len(lines)}A")
        for l in lines:sys.stderr.write("\r\x1b[2K"+l+"\r\n")
        sys.stderr.flush()
    try:old=_set_cbreak(0)
