    sys.stderr.write("\x1b[9A")
    for _ in range(9):sys.stderr.write("\r\x1b[2K\x1b[1B")
    sys.stderr.write("\x1b[9A")
    chosen=[opt for opt,sel in zip(options,selected) if sel]
    sys.stderr.write(f"Bindings: {', '.join(chosen)}\r\n"+"\x1b[?25h")
    return {opt:sel for opt,sel in zip(options,selected)}

def _confirm(label):
    sys.stderr.write(f"? {label} (y/n) ›"+"\x1b[?25l");sys.stderr.flush()
    try:old=_set_cbreak(0)
    except Exception:old=None
    try:
        while True:
            key=_read_key()
            if key in ('y','Y'):
                sys.stderr.write(f"\r\x1b[2K✔ {label} · yes\r\n"+"\x1b[?25h");return True
            if key in ('n','N'):
                sys.stderr.write(f"\r\x1b[2K✔ {label} · no\r\n"+"\x1b[?25h");return False
            if key=='\x03':raise KeyboardInterrupt()
    finally:
        if old is not None:_restore(0,old)
        sys.stderr.write("\x1b[?25h")
