            self.end_headers()
            if self.command!="HEAD":self.wfile.write(body)
        def do_GET(self):self._handle()
        def do_POST(self):self._handle()
        def do_HEAD(self):self._handle()
        def _handle(self):
            # Drain a request body if present
            length=int(self.headers.get('Content-Length') or 0)
            if length:
                try:self.rfile.read(length)
                except Exception:pass
            path=self.path.split('?',1)[0]
            if path=="/":self._send(200,"text/html",index_bytes)
            elif path=="/tree-sitter-parser.wasm":self._send(200,"application/wasm",wasm_bytes)
            else:self._send(404,"text/html",b"Not found")
    class Server(HTTPServer):
        allow_reuse_address=True
        def server_bind(self):
            self.socket.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);super().server_bind()
    server=None;port=8000
    while True:
        try:server=Server(("127.0.0.1",port),Handler);break
        except OSError:port+=1
    url=f"http://127.0.0.1:{port}"
    sys.stderr.write(f"Started playground on: {url}\n");sys.stderr.flush()
    if not parsed.values.get("quiet"):
        if not open_browser(url):
            sys.stderr.write(f"\x1b[31mError:\x1b[0m Failed to open '{url}' in a web browser\n")
    try:server.serve_forever()
    except KeyboardInterrupt:return 130
    return 0
