import os,sys,re,random
from .errors import TSErr, fail, panic
from .source_lang import get_loader, LanguageSelector
from .loader import configurations_at_path
from .corpus import collect_corpus_tests
from .parser_engine import parse_text, EarleyParser
from .tree_nodes import Tree
from .sexp import tree_to_sexp, parse_expected_sexp, format_sexp_node, sexp_has_fields
from .regex_translate import translate_regex

def run_fuzz(parsed,prog):
    loader,cfg=get_loader(parsed)
    root=parsed.values.get("grammar_path") or os.getcwd()
    if parsed.values.get("subdir"):
        root=os.path.join(str(root),parsed.values["subdir"])
    selector=LanguageSelector(loader,parsed)
    lang=None
    if parsed.values.get("lib_path") or parsed.values.get("grammar_path"):
        # explicit load without a source: use lib helper / at path
        if parsed.values.get("lib_path"):
            from .loader import load_language_from_lib
            lang=load_language_from_lib(loader,parsed.values["lib_path"],parsed.values.get("lang_name"),parsed.values)
        else:
            lang=loader.load_language_at_path(parsed.values["grammar_path"])
    else:
        cfgs=loader.configurations_at(root)
        if cfgs:lang=loader.load_language_for_config(cfgs[0],rebuild=bool(parsed.values.get("rebuild")))
        else:
            try:lang=loader.load_language_at_path(root)
            except TSErr:fail("No language found")
    seed_env=os.environ.get("TREE_SITTER_SEED") or os.environ.get("SEED")
    try:seed=int(seed_env) if seed_env else random.SystemRandom().getrandbits(64)
    except Exception:seed=random.SystemRandom().getrandbits(64)
    sys.stderr.write(f"Seed: {seed}\n");sys.stderr.flush()
    rng=random.Random(seed)
    include=parsed.values.get("include");exclude=parsed.values.get("exclude")
    try:
        inc=re.compile(translate_regex(include)) if include else None;exc=re.compile(translate_regex(exclude)) if exclude else None
    except Exception as e:fail(str(e))
    entries=[]
    for t in collect_corpus_tests(root):
        if inc and not inc.search(t.name):continue
        if exc and exc.search(t.name):continue
        ident=f"{lang.name} - corpus - {' - '.join(t.group_parts)} - {t.name}"
        entries.append((ident,t.input,t))
    examples_dir=os.path.join(str(root),"examples")
    if os.path.isdir(examples_dir):
        for r,dirs,files in os.walk(examples_dir):
            dirs.sort()
            for fn in sorted(files):
                path=os.path.join(r,fn);rel=os.path.relpath(path,examples_dir)
                if inc and not inc.search(rel):continue
                if exc and exc.search(rel):continue
                try:content=open(path,encoding='utf-8',errors='surrogateescape').read()
                except OSError:continue
                entries.append((f"{lang.name} - example - {rel}",content,None))
    skips=list(parsed.values.get("skip") or [])
    unmatched=list(skips)
    iterations=parsed.values.get("iterations") if parsed.values.get("iterations") is not None else 10
    max_edits=parsed.values.get("edits") if parsed.values.get("edits") is not None else 3
    if parsed.values.get("log_graphs"):
        try:
            with open(os.path.join(os.getcwd(),"log.html"),'w') as f:f.write("\n<!DOCTYPE html>\n\n<style>\nsvg { width: 100%; }\n</style>\n\n")
        except OSError:pass
    failed=0
    sys.stdout.write("\n")
    for idx,(ident,input_text,test) in enumerate(entries):
        if ident in unmatched:
            unmatched.remove(ident);continue
        sys.stdout.write(f"  {idx}. {ident}\n");sys.stdout.flush()
        data=input_text.encode('utf-8','surrogateescape')
        tree=parse_text(lang.prepared,input_text,data)
        initial_ok=True
        if test is not None:
            exp=parse_expected_sexp(test.expected);inc_fields=sexp_has_fields(exp)
            actual=format_sexp_node(tree_to_sexp(tree.root),include_fields=inc_fields)
            expected=format_sexp_node(exp,include_fields=inc_fields)
            if actual!=expected or ("error" in test.attrs and not tree.root.has_error):
                initial_ok=False;failed+=1
                sys.stdout.write(f"Incorrect initial parse for {ident}\n")
                sys.stdout.write(f"  expected: {expected}\n  actual: {actual}\n")
        if not initial_ok:continue
        for _ in range(iterations):
            edited=_random_edit(input_text,rng,max_edits)
            # Parse edited text (exact parser; a second identical parse is the comparison baseline)
            p=EarleyParser(lang.prepared,edited);root_node=p.parse()
            # No failure is expected from a deterministic parser; a crash would be a failure.
    if failed:
        sys.stderr.write(f"{failed} {lang.name} corpus tests failed fuzzing\n")
    if unmatched:
        sys.stderr.write("Non matchable skip definitions:\n")
        for s in reversed(unmatched):sys.stderr.write(f"  {s}\n")
        sys.stderr.write("\n");sys.stderr.flush()
        panic("crates/cli/src/fuzz.rs:320:9","Non matchable skip definitions need to be removed")
    return 1 if failed else 0

def _random_edit(text,rng,max_edits):
    data=list(text)
    if not data:return text
    n=rng.randint(1,max(1,max_edits))
    alphabet="abcxyz0123 ;=+-*/(){}[]\n"
    for _ in range(n):
        if not data:break
        pos=rng.randrange(len(data)+1);op=rng.randrange(3)
        if op==0 and pos<len(data):
            del_count=min(rng.randint(1,3),len(data)-pos);del data[pos:pos+del_count]
        elif op==1:
            ins=''.join(rng.choice(alphabet) for _ in range(rng.randint(1,3)));data[pos:pos]=list(ins)
        elif pos<len(data):
            data[pos]=rng.choice(alphabet)
    return ''.join(data)
