# --- Unicode property / POSIX support (appended helpers used by translate via monkey patch below) ---
import unicodedata
_category_ranges_cache={}
def _category_ranges(cats):
    key=tuple(sorted(cats))
    if key in _category_ranges_cache:return _category_ranges_cache[key]
    ranges=[];start=None;prev=None
    getcat=unicodedata.category
    for cp in range(0x110000):
        # surrogates have category Cs; skip matching those unless requested
        inside=getcat(chr(cp)) in cats
        if inside and start is None:start=cp;prev=cp
        elif inside:prev=cp
        elif start is not None:ranges.append((start,prev));start=None
    if start is not None:ranges.append((start,prev))
    _category_ranges_cache[key]=ranges;return ranges

def _char_class_escape(cp):
    ch=chr(cp)
    if ch in '\\^-]':return '\\'+ch
    if cp<0x20 or cp==0x7f:return f'\\x{cp:02x}'
    if cp<=0xffff:return ch if ch.isprintable() else f'\\u{cp:04x}'
    return ch if ch.isprintable() else f'\\U{cp:08x}'

def _ranges_to_class_body(ranges):
    parts=[]
    for a,b in ranges:
        if a==b:parts.append(_char_class_escape(a))
        elif b==a+1:parts.append(_char_class_escape(a));parts.append(_char_class_escape(b))
        else:parts.append(_char_class_escape(a)+'-'+_char_class_escape(b))
    return ''.join(parts)

def _property_body(name):
    n=name.strip()
    low=n.lower().replace('_','').replace(' ','').replace('-','')
    catmap={
      'l':['Lu','Ll','Lt','Lm','Lo'],'letter':['Lu','Ll','Lt','Lm','Lo'],
      'lu':['Lu'],'ll':['Ll'],'lt':['Lt'],'lm':['Lm'],'lo':['Lo'],
      'n':['Nd','Nl','No'],'nd':['Nd'],'nl':['Nl'],'no':['No'],
      'm':['Mn','Mc','Me'],'mn':['Mn'],'mc':['Mc'],'me':['Me'],
      'p':['Pc','Pd','Ps','Pe','Pi','Pf','Po'],'punct':['Pc','Pd','Ps','Pe','Pi','Pf','Po'],
      's':['Sm','Sc','Sk','So'],'z':['Zs','Zl','Zp'],'c':['Cc','Cf','Cs','Co','Cn'],
      'alpha':['Lu','Ll','Lt','Lm','Lo','Nl'],'alphabetic':['Lu','Ll','Lt','Lm','Lo','Nl'],
      'alnum':['Lu','Ll','Lt','Lm','Lo','Nd','Nl','No'],
      'digit':['Nd'],'lower':['Ll'],'upper':['Lu'],'cntrl':['Cc'],
    }
    if low in ('space','whitespace','white space'.replace(' ','')):
        return '\\s'
    if low=='word':return '\\w'
    if low=='blank':return ' \\t'
    if low=='xdigit':return '0-9A-Fa-f'
    if low in catmap:return _ranges_to_class_body(_category_ranges(catmap[low]))
    # General_Category=... or gc=...
    if '=' in n:
