{"command":"cat >> app/tree_sitter_cli/parser_c.py << 'PY'

def _flat_alternatives(expr,field=False,alias=False):
    if not isinstance(expr,dict):return [[]]
    t=expr.get("type")
    if t=="BLANK":return [[]]
    if t in ("STRING","PATTERN","SYMBOL"):return [[(field,alias)]]
    if t=="SEQ":
        alts=[[]]
        for m in expr.get("members",[]):
            sub=_flat_alternatives(m,field,alias);alts=[a+b for a in alts for b in sub]
        return alts
    if t=="CHOICE":
        out=[]
        for m in expr.get("members",[]):out.extend(_flat_alternatives(m,field,alias))
        return out
    if t in ("REPEAT","REPEAT1"):return [[(field,alias)]]
    if t=="FIELD":return _flat_alternatives(expr.get("content"),True,alias)
    if t=="ALIAS":
        # an aliased symbol/token is one step; an aliased seq becomes one wrapper step in alias sequences
        inner=_flat_alternatives(expr.get("content"),field,True)
        return [[(field,True)] for _ in inner] if inner else [[(field,True)]]
    if t in ("TOKEN","IMMEDIATE_TOKEN"):return [[(field,alias)]]
    if t in ("PREC","PREC_LEFT","PREC_RIGHT","PREC_DYNAMIC","RESERVED"):return _flat_alternatives(expr.get("content"),field,alias)
    return [[]]

def _production_stats(raw):
    max_len=1;prod_ids=1
    for name,expr in (raw.get("rules") or {}).items():
        for alt in _flat_alternatives(expr):
            max_len=max(max_len,len(alt))
            if any(f or a for f,a in alt):prod_ids+=1
    return max_len,prod_ids

def _collect_aliases(expr,out=None):
    if out is None:out=set()
    if isinstance(expr,dict):
        if expr.get("type")=="ALIAS" and expr.get("value") is not None:out.add((expr.get("value"),bool(expr.get("named"))))
        for v in expr.values():
            if isinstance(v,dict):_collect_aliases(v,out)
            elif isinstance(v,list):
                for x in v:
                    if isinstance(x,dict):_collect_aliases(x,out)
    return out
