use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash,Hasher};
use std::path::{PathBuf,Component};
fn fin(f: impl Fn(&mut DefaultHasher))->u64{let mut h=DefaultHasher::new();f(&mut h);h.finish()}
fn main(){
 let targets=[("a",0x5efaa56e1b6d9df7u64),("/tmp/out.so",0xd7fb2f3220509ed1)];
 for init in 0..6 {
  for per in 0..10 {
   for sep in 0..6 {
    let mut ok=true;
    for (p,t) in targets {
      let path=PathBuf::from(p);
      let comps:Vec<_>=path.components().filter(|c|matches!(c,Component::Normal(_)|Component::ParentDir|Component::CurDir)).collect();
      let v=fin(|h|{
        match init {0=>{},1=>h.write_usize(p.len()),2=>h.write_usize(comps.len()),3=>h.write_u8(0),4=>h.write_u8(1),_=>h.write_u64(0)}
        for c in &comps {
          match per {
            0=>c.as_os_str().hash(h),
            1=>h.write(c.as_os_str().as_encoded_bytes()),
            2=>{h.write_usize(c.as_os_str().len());h.write(c.as_os_str().as_encoded_bytes())},
            3=>c.hash(h),
            4=>{h.write_length_prefix_placeholder(c.as_os_str().len());h.write(c.as_os_str().as_encoded_bytes())},
            5=>{c.as_os_str().as_encoded_bytes().hash(h)},
            6=>{for b in c.as_os_str().as_encoded_bytes(){b.hash(h)}},
            7=>{h.write_usize(c.as_os_str().len()+1);h.write(c.as_os_str().as_encoded_bytes())},
            8=>{h.write_u8(c.as_os_str().len() as u8);h.write(c.as_os_str().as_encoded_bytes())},
            _=>{h.write_isize(4);c.as_os_str().hash(h)},
          }
          match sep {0=>{},1=>h.write_u8(0xff),2=>h.write_u8(0),3=>h.write_u8(b'/'),4=>h.write_usize(0),_=>h.write_u8(1)}
        }
      });
      if v!=t {ok=false;break;}
    }
    if ok{println!("MATCH init{} per{} sep{}",init,per,sep)}
   }
  }
 }
 println!("done");
}
